INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('SOCI.G8.POLITI.CITIZENSHIP.a', 'SOCI.G8.POLITI.CITIZENSHIP', 'a', 'describe qualities of a global citizen in an interconnected society', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('SOCI.G8.POLITI.CITIZENSHIP.b', 'SOCI.G8.POLITI.CITIZENSHIP', 'b', 'explore ways in which Nobel Prize nominees responded to injustice situations in the society', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
