INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.SOCIAL.SELF_IMPROVEMENT.PERSONALITY', 'SOCI.G8.SOCIAL.SELF_IMPROVEMENT', 'social_studies', 8, 'Describe personality traits and how values shape them', ARRAY['SOCI.G8.SOCIAL.SELF_IMPROVEMENT.a']::text[], 'The child names traits (honest, confident, shy, patient, optimistic, hardworking, impatient) from what a person does, tells a trait (how a person usually is) from a feeling (how a person is at one moment), and says values such as honesty and respect shape traits. The child does not say traits can never change. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the trait from a short story","tell a trait from a feeling","say how a value shapes a trait","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM', 'SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT', 'social_studies', 8, 'Say what self-esteem is and the effects of healthy and unhealthy self-esteem', ARRAY['SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.a', 'SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.b']::text[], 'The child says self-esteem is how a person values themselves, picks signs of healthy self-esteem (trying new things, accepting mistakes, respecting others) and of unhealthy self-esteem (low: withdrawing, giving up, being bullied; inflated: boasting, looking down on others), and does not say self-esteem means boasting. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what self-esteem is","pick a sign of healthy self-esteem","pick an effect of low or inflated self-esteem","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS', 'SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI', 'social_studies', 8, 'Put the steps of a community service project in order', ARRAY['SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.a', 'SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.b', 'SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.c', 'SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.d', 'SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.e']::text[], 'The child puts the steps in order (identify a problem or gap, design a solution, plan how to carry it out, carry out the plan, report on the project), says what each step does, and does not skip planning or write the report before the work. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put the steps in order","say what each step does","say why a report is written","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.EVOLUTION', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_', 'social_studies', 8, 'Describe the scientific theory of human origin and the changes in early humans', ARRAY['SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.a', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.b', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.c']::text[], 'The child says the scientific theory is that humans slowly changed (evolved) over millions of years from earlier ape-like ancestors, puts the early humans in order (Australopithecus, Homo habilis, Homo erectus, Homo sapiens), names the changes (walking upright, a bigger brain, making and using tools, using fire) and the evidence (fossils and tools). The child does not say humans come from the monkeys alive today. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put the early humans in order","say what changed","say what the evidence is","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.CRADLE_AFRICA', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_', 'social_studies', 8, 'Say why Africa is the cradle of humanity and how early human remains are kept safe', ARRAY['SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.d', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.e', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.f']::text[], 'The child says the oldest fossils of early humans have been found in Africa, in East Africa''s Rift Valley (Olduvai Gorge in Tanzania, Koobi Fora near Lake Turkana in Kenya) and elsewhere in Africa, names the Leakey family and the Turkana Boy, and picks ways to preserve remains (protected sites, careful digging, museums, labels and records, controlled storage). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a reason for Africa","pick a famous site","pick how remains are preserved","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.PEOPLE.EARLY_CIVILISATION.SWAHILI', 'SOCI.G8.PEOPLE.EARLY_CIVILISATION', 'social_studies', 8, 'Describe the Swahili civilisation and what it gave to the modern world', ARRAY['SOCI.G8.PEOPLE.EARLY_CIVILISATION.a', 'SOCI.G8.PEOPLE.EARLY_CIVILISATION.b']::text[], 'The child names Swahili city-states (Mombasa, Malindi, Lamu, Kilwa, Zanzibar), says the Swahili traded gold, ivory, cloth, timber and other goods by dhow with Arabia, Persia, India and China using the monsoon winds, built coral-stone houses and mosques, and gave the Kiswahili language and a coastal culture. The child does not say Kiswahili is Arabic. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a Swahili city-state","say what the Swahili traded and with whom","say what the civilisation gave us","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.TRANS_SAHARAN', 'SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD', 'social_studies', 8, 'Say how the Trans-Saharan slave trade began, was organised and what it did to Africa', ARRAY['SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.a', 'SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.b', 'SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.c']::text[], 'The child says the trade crossed the Sahara by camel caravans between West and Central Africa and North Africa, names factors (a demand for labour in North Africa and beyond, raiding and wars, the camel and the desert trade routes), says caravans were led by guides and traders along routes with oases, and names effects (loss of lives, families broken, villages emptied, fear and insecurity). The child does not say the trade went by sea. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a factor","say how it was carried out","pick an effect","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.POPULATION', 'SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR', 'social_studies', 8, 'Say the causes and effects of population growth and the types of migration in Africa', ARRAY['SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.a', 'SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.b', 'SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.c']::text[], 'The child says population grows when births are more than deaths (a high birth rate, fewer deaths from better health care and food) and by people moving in, names effects (pressure on land, food, houses, schools and jobs), tells types of migration (rural-urban, between countries, forced by war or drought and by choice), and says Kenya had about 47.6 million people at the 2019 census and a young population. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a cause of growth","pick an effect of growth","pick a type of migration","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.DIVERSITY', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO', 'social_studies', 8, 'Describe the social and cultural diversity of Kenya and how to build healthy self-esteem within it', ARRAY['SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.a', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.b']::text[], 'The child says Kenya has more than forty communities with their own languages, foods, dress and customs and several religions, names respect and learning about others as the way to live together, and says healthy self-esteem grows by being proud of one''s own culture while respecting others. The child does not say one culture is better. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a sign of diversity","pick the way to treat people who are different","say how to build healthy self-esteem","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.PEER_PRESSURE', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO', 'social_studies', 8, 'Say how emotions affect people and how to handle peer pressure', ARRAY['SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.c', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.d']::text[], 'The child says emotions change how a person acts and how others feel (anger can hurt, joy can lift others), and picks ways to refuse peer pressure (say no clearly, give a reason, walk away, keep good friends, ask a trusted adult), and does not give in to be liked. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what emotions do to a person and others","pick how to refuse a pressure","pick a healthy way to handle anger","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.FAMILY_CONFLICT', 'SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU', 'social_studies', 8, 'Say what causes family conflicts and the peaceful ways to resolve them', ARRAY['SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.a', 'SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.b', 'SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.c']::text[], 'The child names causes (poverty, favouritism, disrespect, poor communication, quarrels over property or chores, alcohol), peaceful ways to resolve them (listening, calm talk, apology and forgiveness, help from an elder or counsellor) and communication habits (listening without interrupting, using I-statements, a calm voice), and does not pick shouting, silence for ever or violence. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a cause of conflict","pick a peaceful way to resolve it","pick a good communication habit","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.TOPO_MAPS', 'SOCI.G8.NATURA.MAP_READING_AND_INTERPRE', 'social_studies', 8, 'Read the marginal information, calculate areas and name the ways relief is shown on a topographical map', ARRAY['SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.a', 'SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.b', 'SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.c']::text[], 'The child names the marginal information (title, scale, key, grid reference, north arrow, sheet number, date), calculates an area by counting grid squares (each square 1 square kilometre when the lines are 1 km apart) and picks the ways relief is shown (contours, spot heights, trigonometrical stations, form lines, hill shading and layer colours). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the marginal information","calculate an area by counting squares","pick the way relief is shown","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_AFRICA', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE', 'social_studies', 8, 'Say the factors that influence climate in Africa and describe its major climatic regions', ARRAY['SOCI.G8.NATURA.WEATHER_AND_CLIMATE.a', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE.b']::text[], 'The child names the factors (latitude, altitude, distance from the sea, ocean currents, winds, relief), says temperature falls with height (about 6.5 degrees Celsius for every 1000 metres) and the equator is hot, and describes the equatorial (hot and wet all year, Congo basin), tropical savanna (wet and dry seasons), desert (hot and very dry, Sahara), Mediterranean (rain in winter, dry summer) and mountain regions. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the factor for a place","pick the climatic region","say how altitude changes temperature","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_CHANGE', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE', 'social_studies', 8, 'Say the effects of climate change on the environment and on human activities, and choose ways to address them', ARRAY['SOCI.G8.NATURA.WEATHER_AND_CLIMATE.d', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE.e']::text[], 'The child says climate change is a long-term change in the usual weather (rising temperatures, unreliable rain, longer droughts and heavier floods), gives causes (burning fuels, cutting forests), names effects on the environment and people (dry rivers, crop failure, loss of pasture, floods, disease), and picks responses (planting trees, saving energy, water harvesting, drought-resistant crops, early warning). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick an effect of climate change","pick the action that reduces it","link a climate to the activity it allows","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.NATURA.VEGETATION_IN_AFRICA.VEGETATION', 'SOCI.G8.NATURA.VEGETATION_IN_AFRICA', 'social_studies', 8, 'Say the factors that influence vegetation and describe the major vegetation regions of Africa', ARRAY['SOCI.G8.NATURA.VEGETATION_IN_AFRICA.a', 'SOCI.G8.NATURA.VEGETATION_IN_AFRICA.b', 'SOCI.G8.NATURA.VEGETATION_IN_AFRICA.c']::text[], 'The child says vegetation depends on rainfall, temperature, altitude and soil, names tropical rainforest (Congo basin), savanna (grass with scattered trees, East Africa), desert vegetation (few plants, Sahara), Mediterranean shrubs and mountain vegetation in zones, and picks ways to conserve vegetation (planting trees, protecting forests, controlled grazing, agroforestry), not clearing and burning. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the vegetation for a region","pick the factor","pick a conservation method","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.SITES', 'SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON', 'social_studies', 8, 'Name historical sites in Africa, why they matter and how to conserve them', ARRAY['SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.a', 'SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.b', 'SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.c']::text[], 'The child places selected sites (the Pyramids of Giza in Egypt, Great Zimbabwe in Zimbabwe, the rock-hewn churches of Lalibela in Ethiopia, Timbuktu in Mali, Fort Jesus in Mombasa and Olduvai Gorge in Tanzania), says sites show a people''s history and bring visitors, and picks ways to conserve them (laws, guides, no climbing or writing on walls, repair, museums). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the country of a site","say why a site is important","pick a way to conserve it","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION', 'SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY', 'social_studies', 8, 'Say what the Constitution of Kenya contains, the three arms of government and the principles of leadership and integrity', ARRAY['SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.a', 'SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.b', 'SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.c']::text[], 'The child says the Constitution was promulgated on 27 August 2010, has 18 chapters (the Bill of Rights is Chapter 4 and Leadership and Integrity is Chapter 6), names the three arms (the Legislature makes laws, the Executive carries them out, the Judiciary interprets them and settles disputes) and the principles of leadership (selection on merit, objectivity, selfless service, integrity, accountability, discipline). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the arm for a task","pick the chapter","pick a principle of leadership","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.POLITI.HUMAN_RIGHTS.HUMAN_RIGHTS', 'SOCI.G8.POLITI.HUMAN_RIGHTS', 'social_studies', 8, 'Outline the rights of the child in Kenya and who protects them', ARRAY['SOCI.G8.POLITI.HUMAN_RIGHTS.a', 'SOCI.G8.POLITI.HUMAN_RIGHTS.c', 'SOCI.G8.POLITI.HUMAN_RIGHTS.d']::text[], 'The child names rights of the child in Kenya (a name and nationality, free and compulsory basic education, health care, food and shelter, protection from abuse, neglect, child labour and harmful practices), names who protects them (parents, teachers, the chief, the police, the children''s department, Childline Kenya 116) and says rights come with responsibilities. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a right of the child","pick who protects a child","pick the responsible action","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.POLITI.HUMAN_RIGHTS.HR_COMMUNICATE', 'SOCI.G8.POLITI.HUMAN_RIGHTS', 'social_studies', 8, 'Describe the process of communicating effectively on human rights issues', ARRAY['SOCI.G8.POLITI.HUMAN_RIGHTS.b']::text[], 'The child puts the steps in order (get the facts, choose the right person or office, say the issue clearly and calmly with evidence, listen to the reply, follow up), names channels (a teacher, the chief, the police, the children''s department, Childline 116, the Kenya National Commission on Human Rights) and picks assertive, respectful language over shouting, rumours or silence. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put the steps of raising a rights issue in order","pick who to report to","pick the respectful way to speak up","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G8.POLITI.CITIZENSHIP.CITIZENSHIP', 'SOCI.G8.POLITI.CITIZENSHIP', 'social_studies', 8, 'Name the qualities of a global citizen and the ways East African citizens live in harmony', ARRAY['SOCI.G8.POLITI.CITIZENSHIP.a', 'SOCI.G8.POLITI.CITIZENSHIP.b', 'SOCI.G8.POLITI.CITIZENSHIP.c']::text[], 'The child names qualities (respect for others, care for the environment, concern for justice, being informed and taking part), says Wangari Maathai won the Nobel Peace Prize in 2004 for the Green Belt Movement, names members of the East African Community (Kenya, Uganda, Tanzania, Rwanda, Burundi, South Sudan, the Democratic Republic of the Congo and Somalia) and factors for harmony (respect, a shared language in Kiswahili, trade, peaceful talks). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the quality of a global citizen","pick a member of the East African Community","pick a factor for harmony","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
