INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_ABILITIES', 'skill', 'helpful', 'Knowing one''s own strengths (Grade 7) is the root of healthy self-esteem. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
