INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.EVOLUTION', 'SOCI.G7.NATURA.HISTORICAL_INFORMATION.HI_SOURCES', 'skill', 'essential', 'Fossils as archaeological sources (Grade 7) are the evidence for the theory. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
