INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G8.PEOPLE.EARLY_CIVILISATION.SWAHILI', 'SOCI.G7.PEOPLE.SLAVERY_AND_SERVITUDE.SL_INDIAN', 'skill', 'helpful', 'The monsoon and the Indian Ocean routes (Grade 7) carried Swahili trade. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
