INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.TRANS_SAHARAN', 'SOCI.G7.NATURA.MAPS_AND_MAP_WORK.MM_FEATURES', 'skill', 'essential', 'The Sahara and Africa''s features (Grade 7) are the setting of the trade. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.POPULATION', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_EFFECTS', 'skill', 'essential', 'The effects of high density (Grade 6) are the effects of rapid growth. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
