INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.SOCIAL.SELF_IMPROVEMENT.PERSONALITY.M_G8_PT_TRAIT_FEELING', 'SOCI.G8.SOCIAL.SELF_IMPROVEMENT.PERSONALITY', 'Says a trait and a feeling are the same.', '{"question":"Which is a personality trait?","wrong_answer":"Feeling angry today","correct_answer":"Being patient"}'::jsonb, 'People say "he is angry" both for a moment and for a habit, so the child does not separate the two.', 'Offer "Feeling angry today" next to the right answer in a new question and ask the child to choose.', 'Ask: is it how you usually are, or how you are right now?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.SOCIAL.SELF_IMPROVEMENT.PERSONALITY.M_G8_PT_TRAIT_FIXED', 'SOCI.G8.SOCIAL.SELF_IMPROVEMENT.PERSONALITY', 'Says traits can never change.', '{"question":"Can a person change an unhelpful trait?","wrong_answer":"No, traits never change","correct_answer":"Yes, with effort and good habits"}'::jsonb, 'Adults often say "that is just how she is", so traits sound permanent.', 'Offer "No, traits never change" next to the right answer in a new question and ask the child to choose.', 'Ask the child about a habit they have changed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.SOCIAL.SELF_IMPROVEMENT.PERSONALITY.M_G8_PT_VALUE_TRAIT', 'SOCI.G8.SOCIAL.SELF_IMPROVEMENT.PERSONALITY', 'Says values have no effect on a person''s traits.', '{"question":"How do values shape a person?","wrong_answer":"They do not affect traits","correct_answer":"They guide how a person acts and so shape traits"}'::jsonb, 'Values are taught as rules to follow, not as what slowly shapes a person.', 'Offer "They do not affect traits" next to the right answer in a new question and ask the child to choose.', 'Ask what an honest value does to what a person does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.SOCIAL.SELF_IMPROVEMENT.PERSONALITY.M_G8_PT_LOOKS', 'SOCI.G8.SOCIAL.SELF_IMPROVEMENT.PERSONALITY', 'Judges a person''s personality traits from how they look or dress.', '{"question":"A learner wears old shoes. What can you tell about his personality?","wrong_answer":"He is lazy","correct_answer":"Nothing; traits show in what a person does"}'::jsonb, 'The child links appearance with character from stories and gossip.', 'Offer "He is lazy" next to the right answer and ask the question again in a new context.', 'Ask what the learner actually does in class and at play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM.M_G8_SA_PRIDE', 'SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM', 'Says self-esteem means boasting.', '{"question":"What is self-esteem?","wrong_answer":"Boasting about yourself","correct_answer":"How you value and respect yourself"}'::jsonb, 'People who talk about themselves loudly are called "confident", so the child mixes self-esteem with boasting.', 'Offer "Boasting about yourself" next to the right answer in a new question and ask the child to choose.', 'Ask: can a person be confident and still kind?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM.M_G8_SA_LOW_NO_EFFECT', 'SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM', 'Says low self-esteem has no effect on daily life.', '{"question":"What can low self-esteem lead to?","wrong_answer":"Nothing, it has no effect","correct_answer":"Giving up easily and staying away from others"}'::jsonb, 'Low self-esteem is a feeling the child cannot see, so it seems to change nothing.', 'Offer "Nothing, it has no effect" next to the right answer in a new question and ask the child to choose.', 'Ask how a child who thinks they cannot do anything behaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM.M_G8_SA_HIGH_GOOD', 'SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM', 'Thinks too much self-esteem is always good.', '{"question":"A boy brags that he is better than everyone. What is this?","wrong_answer":"Healthy self-esteem","correct_answer":"Inflated self-esteem"}'::jsonb, 'The child has heard "believe in yourself" and thinks more is always better.', 'Offer "Healthy self-esteem" next to the right answer in a new question and ask the child to choose.', 'Ask how his classmates feel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM.M_G8_SA_MARKS_ONLY', 'SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM', 'Thinks self-esteem depends only on exam marks.', '{"question":"Achieng did badly in one test. Must her self-esteem be low?","wrong_answer":"Yes, marks show your worth","correct_answer":"No, her worth does not depend on one test"}'::jsonb, 'Marks are praised loudly at school.', 'Offer "Yes, marks show your worth" next to the right answer and ask the question again in a new context.', 'List other things Achieng does well.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS.M_G8_CS_ORDER', 'SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS', 'Starts with carrying out the work, before identifying the community problem and designing a solution.', '{"question":"What comes first in a community service project?","wrong_answer":"Carry out the work","correct_answer":"Identify a problem in the community"}'::jsonb, 'Doing feels like the real project, so the child jumps to action.', 'Offer "Carry out the work" next to the right answer in a new question and ask the child to choose.', 'Write the steps on cards and put them in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS.M_G8_CS_SKIP_PLAN', 'SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS', 'Skips the planning step.', '{"question":"What should be done before carrying out the solution?","wrong_answer":"Nothing, start at once","correct_answer":"Plan who does what, with what, and when"}'::jsonb, 'The child thinks a good idea is enough and that planning wastes time.', 'Offer "Nothing, start at once" next to the right answer in a new question and ask the child to choose.', 'Ask what happens when a team starts without a plan.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS.M_G8_CS_REPORT_END', 'SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS', 'Says the report is written before the work.', '{"question":"When is the project report written?","wrong_answer":"Before the work begins","correct_answer":"After the work is done"}'::jsonb, 'The child mixes the report with the plan, both written documents.', 'Offer "Before the work begins" next to the right answer in a new question and ask the child to choose.', 'Ask what a report would say if the work has not happened.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS.M_G8_CS_DESIGN_PLAN', 'SOCI.G8.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS', 'Treats designing a solution and planning as the same step.', '{"question":"What is the difference between designing a solution and planning?","wrong_answer":"They are the same","correct_answer":"Designing chooses what to do; planning says who, when and with what"}'::jsonb, 'Both happen before the work.', 'Offer "They are the same" next to the right answer and ask the question again in a new context.', 'Design: "build a rack for bins". Plan: "who builds it, when, with what wood".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.EVOLUTION.M_G8_EV_ORDER', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.EVOLUTION', 'Puts Homo sapiens first and Australopithecus last, reading the list as newest-first.', '{"question":"Which early human came first?","wrong_answer":"Homo sapiens","correct_answer":"Australopithecus"}'::jsonb, 'The child knows Homo sapiens (people today) best and puts them at the start.', 'Offer "Homo sapiens" next to the right answer in a new question and ask the child to choose.', 'Put the names on a timeline.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.EVOLUTION.M_G8_EV_MONKEY', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.EVOLUTION', 'Says humans come from the monkeys alive today.', '{"question":"What does the scientific theory say about human origin?","wrong_answer":"Humans came from the monkeys we see today","correct_answer":"Humans and apes share earlier ancestors and changed over millions of years"}'::jsonb, 'Pictures often show a monkey turning into a man, so the child thinks today''s monkeys became people.', 'Offer "Humans came from the monkeys we see today" next to the right answer in a new question and ask the child to choose.', 'Ask: do your grandparents come from your cousins?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.EVOLUTION.M_G8_EV_FAST', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.EVOLUTION', 'Says the changes happened in a short time.', '{"question":"How long did the changes take?","wrong_answer":"A few hundred years","correct_answer":"Millions of years"}'::jsonb, 'The child cannot picture millions of years and thinks in lifetimes.', 'Offer "A few hundred years" next to the right answer in a new question and ask the child to choose.', 'Show a long timeline.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.CRADLE_AFRICA.M_G8_CR_WHY', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.CRADLE_AFRICA', 'Says Africa is the cradle because it is the largest or the richest.', '{"question":"Why is Africa called the cradle of humanity?","wrong_answer":"Because it is the biggest continent","correct_answer":"Because the oldest fossils of early humans were found there"}'::jsonb, 'The child links "cradle" with being important, and importance with size or wealth.', 'Offer "Because it is the biggest continent" next to the right answer in a new question and ask the child to choose.', 'Ask what evidence tells us where people began.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.CRADLE_AFRICA.M_G8_CR_PLACE', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.CRADLE_AFRICA', 'Puts Olduvai Gorge in Kenya because it is in the Rift Valley near Kenya.', '{"question":"Where is Olduvai Gorge?","wrong_answer":"Kenya","correct_answer":"Tanzania"}'::jsonb, 'Kenyan fossil sites are taught alongside Olduvai and the child places them all in Kenya.', 'Offer "Kenya" next to the right answer in a new question and ask the child to choose.', 'Find the sites on a map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.CRADLE_AFRICA.M_G8_CR_PRESERVE', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.CRADLE_AFRICA', 'Picks taking fossils home or selling them as a way of keeping them.', '{"question":"Which helps to preserve early human remains?","wrong_answer":"Take them home to show friends","correct_answer":"Keep them in a museum with records"}'::jsonb, 'Keeping something safe at home feels like caring for it.', 'Offer "Take them home to show friends" next to the right answer in a new question and ask the child to choose.', 'Ask what happens to a fossil handled by many hands.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.EVOLUTION.M_G8_EV_TOOLS_LATE', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.EVOLUTION', 'Thinks early humans made no tools until modern times.', '{"question":"Which early humans first made simple stone tools?","wrong_answer":"Only Homo sapiens in modern times","correct_answer":"Homo habilis"}'::jsonb, 'Tools are pictured as modern machines.', 'Offer "Only Homo sapiens in modern times" next to the right answer and ask the question again in a new context.', 'Show a photo of a stone hand axe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.CRADLE_AFRICA.M_G8_CR_TURKANA_BOY_TANZANIA', 'SOCI.G8.PEOPLE.SCIENTIFIC_THEORY_ABOUT_.CRADLE_AFRICA', 'Places the Turkana Boy fossil in Tanzania.', '{"question":"Where was the Turkana Boy fossil found?","wrong_answer":"Tanzania","correct_answer":"Near Lake Turkana in Kenya"}'::jsonb, 'Fossil sites of the region blur.', 'Offer "Tanzania" next to the right answer and ask the question again in a new context.', 'Pin Olduvai and Lake Turkana on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.EARLY_CIVILISATION.SWAHILI.M_G8_SW_WHERE', 'SOCI.G8.PEOPLE.EARLY_CIVILISATION.SWAHILI', 'Names Timbuktu or another inland West African city as a Swahili city-state.', '{"question":"Which of these was a Swahili city-state?","wrong_answer":"Timbuktu","correct_answer":"Kilwa"}'::jsonb, 'Timbuktu is another famous old trading city and the child groups all ancient trade towns together.', 'Offer "Timbuktu" next to the right answer in a new question and ask the child to choose.', 'Find the coast on a map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.EARLY_CIVILISATION.SWAHILI.M_G8_SW_TRADE', 'SOCI.G8.PEOPLE.EARLY_CIVILISATION.SWAHILI', 'Says the Swahili traded first with Europe.', '{"question":"With whom did the Swahili trade by dhow?","wrong_answer":"First with Europe","correct_answer":"With Arabia, Persia, India and China"}'::jsonb, 'Europeans are the traders the child hears about most in African history.', 'Offer "First with Europe" next to the right answer in a new question and ask the child to choose.', 'Look at the monsoon winds on a map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.EARLY_CIVILISATION.SWAHILI.M_G8_SW_LANGUAGE', 'SOCI.G8.PEOPLE.EARLY_CIVILISATION.SWAHILI', 'Says Kiswahili is the Arabic language.', '{"question":"What is Kiswahili?","wrong_answer":"The Arabic language","correct_answer":"A Bantu language with some Arabic words"}'::jsonb, 'Kiswahili has many Arabic words, so the child thinks it is Arabic.', 'Offer "The Arabic language" next to the right answer in a new question and ask the child to choose.', 'Ask which words are Bantu and which came from trade.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.EARLY_CIVILISATION.SWAHILI.M_G8_SW_HOUSES_MUD', 'SOCI.G8.PEOPLE.EARLY_CIVILISATION.SWAHILI', 'Thinks Swahili towns were built only of mud and grass.', '{"question":"What were many Swahili houses and mosques built of?","wrong_answer":"Mud and grass only","correct_answer":"Coral stone"}'::jsonb, 'The child pictures all old houses as mud huts.', 'Offer "Mud and grass only" next to the right answer and ask the question again in a new context.', 'Show photos of coral-stone buildings in Lamu and Gedi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.TRANS_SAHARAN.M_G8_TS_ROUTE', 'SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.TRANS_SAHARAN', 'Says the trade went by sea.', '{"question":"How did traders cross the Sahara?","wrong_answer":"By ship","correct_answer":"By camel caravans"}'::jsonb, 'The Indian Ocean and Atlantic trades used ships, so the child thinks all slave trades did.', 'Offer "By ship" next to the right answer in a new question and ask the child to choose.', 'Ask what travels over a desert.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.TRANS_SAHARAN.M_G8_TS_FACTOR', 'SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.TRANS_SAHARAN', 'Names railways or motor lorries as a factor in the Trans-Saharan trade, centuries before they existed.', '{"question":"Which factor helped the Trans-Saharan trade grow?","wrong_answer":"Railways across the desert","correct_answer":"The camel and a demand for labour in North Africa"}'::jsonb, 'The child pictures desert crossing with modern transport.', 'Offer "Railways across the desert" next to the right answer in a new question and ask the child to choose.', 'Ask what the traders had to cross the desert.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.TRANS_SAHARAN.M_G8_TS_EFFECT', 'SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.TRANS_SAHARAN', 'Says villages grew larger and richer from the trade, missing the loss of people and broken families.', '{"question":"Which was an effect of the Trans-Saharan slave trade?","wrong_answer":"Villages grew larger and richer","correct_answer":"Families were broken and villages emptied"}'::jsonb, 'Trade is usually taught as bringing wealth, so the child expects good effects.', 'Offer "Villages grew larger and richer" next to the right answer in a new question and ask the child to choose.', 'Ask what happens to a village when its young people are taken.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.TRANS_SAHARAN.M_G8_TS_OASIS_NONE', 'SOCI.G8.PEOPLE.TRANS_SAHARAN_SLAVE_TRAD.TRANS_SAHARAN', 'Does not see why oases mattered to the caravans.', '{"question":"Why did caravans stop at oases?","wrong_answer":"For no reason","correct_answer":"To get water and rest in the desert"}'::jsonb, 'The child does not know what an oasis is.', 'Offer "For no reason" next to the right answer and ask the question again in a new context.', 'Show an oasis photo and the route linking them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.POPULATION.M_G8_PG_CAUSE', 'SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.POPULATION', 'Says a rising death rate makes the population grow.', '{"question":"Which helps the population to grow?","wrong_answer":"More deaths than births","correct_answer":"More births than deaths"}'::jsonb, 'The child mixes up birth rate and death rate, both "rates" in the lesson.', 'Offer "More deaths than births" next to the right answer in a new question and ask the child to choose.', 'Ask what happens when births are more than deaths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.POPULATION.M_G8_PG_MIGRATION', 'SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.POPULATION', 'Says migration means only moving to another country.', '{"question":"Which is a type of migration?","wrong_answer":"Only moving to another country","correct_answer":"Moving from the countryside to a town"}'::jsonb, 'Migration is often shown as people crossing borders on the news.', 'Offer "Only moving to another country" next to the right answer in a new question and ask the child to choose.', 'Ask where people in your area have moved to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.POPULATION.M_G8_PG_EFFECT', 'SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.POPULATION', 'Says rapid population growth only brings good things.', '{"question":"What is an effect of rapid population growth?","wrong_answer":"Plenty of jobs and land for all","correct_answer":"Pressure on land, food, houses and jobs"}'::jsonb, 'More people sounds like more workers and more strength.', 'Offer "Plenty of jobs and land for all" next to the right answer in a new question and ask the child to choose.', 'Ask how a small plot feeds a growing family.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.POPULATION.M_G8_PG_HEALTH_NONE', 'SOCI.G8.PEOPLE.POPULATION_GROWTH_IN_AFR.POPULATION', 'Does not link better health care to population growth.', '{"question":"How does better health care make a population grow?","wrong_answer":"It does not","correct_answer":"Fewer people die young, so more live longer"}'::jsonb, 'Health care is seen only as treating sickness.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Compare a family with and without vaccines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.DIVERSITY.M_G8_DV8_ONE_CULTURE', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.DIVERSITY', 'Says Kenya has only one culture.', '{"question":"How many cultures does Kenya have?","wrong_answer":"Only one","correct_answer":"More than forty communities with their own cultures"}'::jsonb, 'The child hears "Kenyan culture" spoken of as one thing.', 'Offer "Only one" next to the right answer in a new question and ask the child to choose.', 'Ask the child to name three communities and a food from each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.DIVERSITY.M_G8_DV8_BETTER', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.DIVERSITY', 'Says one culture is better than the others.', '{"question":"How should we treat other cultures?","wrong_answer":"See ours as better than theirs","correct_answer":"Respect and learn from them"}'::jsonb, 'Pride in one''s own culture slides into thinking it is the best.', 'Offer "See ours as better than theirs" next to the right answer in a new question and ask the child to choose.', 'Ask what we gain from learning about another culture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.DIVERSITY.M_G8_DV8_ESTEEM', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.DIVERSITY', 'Says healthy self-esteem means feeling better than others.', '{"question":"How does healthy self-esteem grow in a diverse society?","wrong_answer":"By feeling better than others","correct_answer":"By being proud of our own culture and respecting others"}'::jsonb, 'Self-esteem is confused with feeling above others.', 'Offer "By feeling better than others" next to the right answer in a new question and ask the child to choose.', 'Ask: can I be proud of my culture and still respect yours?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.PEER_PRESSURE.M_G8_PR_GIVE_IN', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.PEER_PRESSURE', 'Says a person should give in to peer pressure to be liked.', '{"question":"A friend pushes you to do wrong. What should you do?","wrong_answer":"Give in to be liked","correct_answer":"Say no clearly and walk away"}'::jsonb, 'Being liked by friends feels very important at this age.', 'Offer "Give in to be liked" next to the right answer in a new question and ask the child to choose.', 'Role play the refusal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.PEER_PRESSURE.M_G8_PR_HIDE', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.PEER_PRESSURE', 'Says feelings should always be hidden.', '{"question":"What should you do with a strong feeling?","wrong_answer":"Hide it for ever","correct_answer":"Name it and talk to a trusted person"}'::jsonb, 'The child has been told to "be strong" and not show feelings.', 'Offer "Hide it for ever" next to the right answer in a new question and ask the child to choose.', 'Ask who they can talk to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.PEER_PRESSURE.M_G8_PR_ANGER', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.PEER_PRESSURE', 'Says acting on anger at once is best.', '{"question":"What is a healthy way to handle anger?","wrong_answer":"Hit the person at once","correct_answer":"Pause, breathe and then talk calmly"}'::jsonb, 'Acting at once feels like standing up for yourself.', 'Offer "Hit the person at once" next to the right answer in a new question and ask the child to choose.', 'Practise a pause and a calm sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.DIVERSITY.M_G8_DV8_RELIGION_ONE', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.DIVERSITY', 'Thinks all Kenyans follow one religion.', '{"question":"How many religions are practised in Kenya?","wrong_answer":"Only one","correct_answer":"Several, such as Christianity, Islam, Hinduism and African traditional religion"}'::jsonb, 'The child knows their own faith best.', 'Offer "Only one" next to the right answer and ask the question again in a new context.', 'List places of worship in the town.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.PEER_PRESSURE.M_G8_PR_GOOD_PRESSURE', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.PEER_PRESSURE', 'Thinks all peer pressure is bad.', '{"question":"Friends encourage Juma to join the reading club. Is this peer pressure bad?","wrong_answer":"Yes, all peer pressure is bad","correct_answer":"No, this is positive peer pressure"}'::jsonb, 'Peer pressure is taught with bad examples.', 'Offer "Yes, all peer pressure is bad" next to the right answer and ask the question again in a new context.', 'Sort examples into positive and negative pressure.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.FAMILY_CONFLICT.M_G8_FC_WIN', 'SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.FAMILY_CONFLICT', 'Thinks the aim is to win the argument.', '{"question":"What is the aim of resolving a family conflict?","wrong_answer":"To win the argument","correct_answer":"To understand each other and make peace"}'::jsonb, 'Arguments at home often end with someone "winning", so the child sees that as the aim.', 'Offer "To win the argument" next to the right answer in a new question and ask the child to choose.', 'Ask what happens when one side wins and the other is hurt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.FAMILY_CONFLICT.M_G8_FC_SILENCE', 'SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.FAMILY_CONFLICT', 'Says silence for ever is a way to resolve conflict.', '{"question":"Which is a peaceful way to resolve a conflict?","wrong_answer":"Not speaking to each other for months","correct_answer":"Talking calmly and listening"}'::jsonb, 'Not speaking stops the shouting, so it looks like peace.', 'Offer "Not speaking to each other for months" next to the right answer in a new question and ask the child to choose.', 'Ask how silence changes the problem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.FAMILY_CONFLICT.M_G8_FC_FIGHT', 'SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.FAMILY_CONFLICT', 'Picks asking an elder for help as the non-peaceful choice, so treats shouting and hitting as acceptable.', '{"question":"Which is NOT a peaceful way?","wrong_answer":"Asking an elder to help","correct_answer":"Shouting and hitting"}'::jsonb, 'The child has seen shouting end quarrels at home and reads the question the wrong way round.', 'Offer "Asking an elder to help" next to the right answer in a new question and ask the child to choose.', 'Ask who is hurt when people shout and hit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.FAMILY_CONFLICT.M_G8_FC_YOU_STATEMENT', 'SOCI.G8.PEOPLE.PEACEFUL_CONFLICT_RESOLU.FAMILY_CONFLICT', 'Thinks blaming words ("You always...") help solve a family conflict.', '{"question":"Which sentence helps solve a quarrel with a sibling?","wrong_answer":"\"You always take my things!\"","correct_answer":"\"I feel upset when my things are taken. Please ask first.\""}'::jsonb, 'The child expresses feelings by blaming.', 'Offer ""You always take my things!"" next to the right answer and ask the question again in a new context.', 'Rewrite blaming sentences as I-statements.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.TOPO_MAPS.M_G8_TM_KEY', 'SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.TOPO_MAPS', 'Says the key shows direction.', '{"question":"What does the key (legend) of a map show?","wrong_answer":"The direction of north","correct_answer":"What the signs on the map mean"}'::jsonb, 'The key and the north arrow sit together in the margin.', 'Offer "The direction of north" next to the right answer in a new question and ask the child to choose.', 'Look at the key of a real map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.TOPO_MAPS.M_G8_TM_AREA', 'SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.TOPO_MAPS', 'Adds the numbers of squares instead of counting the area correctly.', '{"question":"A lake covers 4 grid squares by 3 grid squares of 1 square kilometre each. What is its area?","wrong_answer":"7 square kilometres","correct_answer":"12 square kilometres"}'::jsonb, 'The child adds the two sides as for perimeter instead of multiplying for area.', 'Offer "7 square kilometres" next to the right answer in a new question and ask the child to choose.', 'Draw the squares and count them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.TOPO_MAPS.M_G8_TM_RELIEF', 'SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.TOPO_MAPS', 'Names the scale or the key as a way of showing relief, instead of contours, spot heights or hill shading.', '{"question":"Which shows relief on a topographical map?","wrong_answer":"The scale","correct_answer":"Contours"}'::jsonb, 'All margin items are learnt in one list, so the child picks any of them.', 'Offer "The scale" next to the right answer in a new question and ask the child to choose.', 'Look at a real map for the lines that join heights.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.TOPO_MAPS.M_G8_TM_CONTOUR_ROAD', 'SOCI.G8.NATURA.MAP_READING_AND_INTERPRE.TOPO_MAPS', 'Reads a brown contour line as a road or a path.', '{"question":"A brown curved line on a topographical map joins points of the same height. What is it?","wrong_answer":"A road","correct_answer":"A contour"}'::jsonb, 'Lines on maps are usually roads.', 'Offer "A road" next to the right answer and ask the question again in a new context.', 'Check the key: contours are brown lines labelled with heights.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_AFRICA.M_G8_CL_LAT', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_AFRICA', 'Says only latitude affects climate.', '{"question":"Which factors affect climate?","wrong_answer":"Only latitude","correct_answer":"Latitude, altitude, distance from the sea, currents and winds"}'::jsonb, 'Latitude is the first factor taught and the easiest to see on a map.', 'Offer "Only latitude" next to the right answer in a new question and ask the child to choose.', 'Compare Nairobi and Mombasa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_AFRICA.M_G8_CL_ALT', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_AFRICA', 'Says it gets hotter as you go higher.', '{"question":"What happens to temperature as you climb a mountain?","wrong_answer":"It rises","correct_answer":"It falls"}'::jsonb, 'Higher places are closer to the sun, so the child thinks they are hotter.', 'Offer "It rises" next to the right answer in a new question and ask the child to choose.', 'Think of the snow on Mount Kenya at the equator.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_AFRICA.M_G8_CL_REGION', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_AFRICA', 'Calls the desert climate hot and wet all year, swapping it with the equatorial climate.', '{"question":"Which climate has hot, wet weather all year?","wrong_answer":"Desert","correct_answer":"Equatorial"}'::jsonb, 'Both are "hot" climates and the child matches by temperature only.', 'Offer "Desert" next to the right answer in a new question and ask the child to choose.', 'Link the Congo basin with rain every day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_AFRICA.M_G8_CL_CURRENT_NONE', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_AFRICA', 'Does not know ocean currents affect climate.', '{"question":"How can a cold ocean current affect a coast?","wrong_answer":"It cannot","correct_answer":"It cools the air and makes the coast drier"}'::jsonb, 'Oceans seem far from weather on land.', 'Offer "It cannot" next to the right answer and ask the question again in a new context.', 'Use the Namib desert next to the cold Benguela current (to confirm).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_CHANGE.M_G8_CC_WEATHER_SAME', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_CHANGE', 'Thinks one hot day or one heavy storm is climate change.', '{"question":"Is one very hot day proof of climate change?","wrong_answer":"Yes","correct_answer":"No, climate change is a change in the usual weather over many years"}'::jsonb, 'Weather and climate are confused again.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Show a temperature line over 50 years, not one day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_CHANGE.M_G8_CC_TREES_CAUSE', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_CHANGE', 'Thinks planting trees causes climate change.', '{"question":"Which action can make climate change worse?","wrong_answer":"Planting trees","correct_answer":"Cutting forests and burning fuels"}'::jsonb, 'The child links any change in nature with harm.', 'Offer "Planting trees" next to the right answer and ask the question again in a new context.', 'Show trees taking in carbon dioxide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_CHANGE.M_G8_CC_FARMERS_NONE', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_CHANGE', 'Thinks climate change does not affect farmers.', '{"question":"How can unreliable rain affect farmers?","wrong_answer":"It does not","correct_answer":"Crops fail and animals lack pasture"}'::jsonb, 'The child sees climate as distant.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Ask what happens to maize when the rains fail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_CHANGE.M_G8_CC_NOTHING_TO_DO', 'SOCI.G8.NATURA.WEATHER_AND_CLIMATE.CLIMATE_CHANGE', 'Thinks individuals can do nothing about climate change.', '{"question":"Give one thing a learner can do about climate change.","wrong_answer":"Nothing","correct_answer":"Plant trees, save energy and avoid waste"}'::jsonb, 'The problem seems too big for one person.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'List small actions and add up a whole school doing them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.VEGETATION_IN_AFRICA.VEGETATION.M_G8_VG_REGION', 'SOCI.G8.NATURA.VEGETATION_IN_AFRICA.VEGETATION', 'Puts desert scrub in the Congo basin, matching vegetation to the wrong climate.', '{"question":"Which vegetation grows in the Congo basin?","wrong_answer":"Desert scrub","correct_answer":"Tropical rainforest"}'::jsonb, 'The child has not linked the wettest region to the thickest forest.', 'Offer "Desert scrub" next to the right answer in a new question and ask the child to choose.', 'Link rainfall with the thickness of the trees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.VEGETATION_IN_AFRICA.VEGETATION.M_G8_VG_FACTOR', 'SOCI.G8.NATURA.VEGETATION_IN_AFRICA.VEGETATION', 'Names something unrelated, such as the colour of the sky, as a factor of vegetation.', '{"question":"Which factor affects vegetation?","wrong_answer":"The colour of the sky","correct_answer":"Rainfall"}'::jsonb, 'The child guesses without linking plants to rain, heat, height and soil.', 'Offer "The colour of the sky" next to the right answer in a new question and ask the child to choose.', 'Ask what plants need to grow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.VEGETATION_IN_AFRICA.VEGETATION.M_G8_VG_CONSERVE', 'SOCI.G8.NATURA.VEGETATION_IN_AFRICA.VEGETATION', 'Picks burning bushes to clear land as a way of conserving vegetation.', '{"question":"Which method conserves vegetation?","wrong_answer":"Burning bushes to clear land","correct_answer":"Planting trees and protecting forests"}'::jsonb, 'Burning is seen to bring fresh grass, so it seems to help plants.', 'Offer "Burning bushes to clear land" next to the right answer in a new question and ask the child to choose.', 'Ask what happens to the soil when a forest is cut.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.VEGETATION_IN_AFRICA.VEGETATION.M_G8_VG_MED_EAST', 'SOCI.G8.NATURA.VEGETATION_IN_AFRICA.VEGETATION', 'Places Mediterranean vegetation in East Africa.', '{"question":"Where is Mediterranean vegetation found in Africa?","wrong_answer":"East Africa","correct_answer":"The far north and far south (North Africa and the Cape)"}'::jsonb, 'The name is unfamiliar.', 'Offer "East Africa" next to the right answer and ask the question again in a new context.', 'Shade the two Mediterranean areas on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.SITES.M_G8_HS_PLACE', 'SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.SITES', 'Puts Great Zimbabwe in Egypt, linking every ancient stone monument to Egypt.', '{"question":"In which country is Great Zimbabwe?","wrong_answer":"Egypt","correct_answer":"Zimbabwe"}'::jsonb, 'Egypt''s pyramids are the best-known monuments, so the child places other great stone works there.', 'Offer "Egypt" next to the right answer in a new question and ask the child to choose.', 'Find the sites on a map of Africa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.SITES.M_G8_HS_USELESS', 'SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.SITES', 'Says historical sites have no use.', '{"question":"Why are historical sites important?","wrong_answer":"They have no use today","correct_answer":"They show our history and bring visitors"}'::jsonb, 'Old places look unused, so the child thinks they serve no purpose.', 'Offer "They have no use today" next to the right answer in a new question and ask the child to choose.', 'Ask what we would lose without them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.SITES.M_G8_HS_CONSERVE', 'SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.SITES', 'Picks an action that damages a site.', '{"question":"How should visitors behave at a historical site?","wrong_answer":"Climb the walls and write names","correct_answer":"Follow the guide and leave things as they are"}'::jsonb, 'Visitors are sometimes seen climbing or writing on walls.', 'Offer "Climb the walls and write names" next to the right answer in a new question and ask the child to choose.', 'Ask what happens when everyone writes on a wall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.SITES.M_G8_HS_TIMBUKTU_EAST', 'SOCI.G8.NATURA.HISTORICAL_SITES_AND_MON.SITES', 'Places Timbuktu in East Africa.', '{"question":"In which country is Timbuktu?","wrong_answer":"Kenya","correct_answer":"Mali, in West Africa"}'::jsonb, 'The name is famous but unplaced.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Pin it on the Africa map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION.M_G8_CN_ARM', 'SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION', 'Says the Legislature interprets the law and settles disputes, giving the Judiciary''s work to Parliament.', '{"question":"Which arm interprets the law and settles disputes?","wrong_answer":"The Legislature","correct_answer":"The Judiciary"}'::jsonb, 'Parliament debates laws, so the child thinks it also explains and judges them.', 'Offer "The Legislature" next to the right answer in a new question and ask the child to choose.', 'Link each arm to one verb: make, carry out, interpret.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION.M_G8_CN_CHAPTER', 'SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION', 'Says the Bill of Rights is Chapter 6, swapping it with Leadership and Integrity.', '{"question":"Which chapter is the Bill of Rights?","wrong_answer":"Chapter 6","correct_answer":"Chapter 4"}'::jsonb, 'Chapters 4 and 6 are both taught in this sub-strand and the numbers swap.', 'Offer "Chapter 6" next to the right answer in a new question and ask the child to choose.', 'Look at the table of contents.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION.M_G8_CN_PRINCIPLE', 'SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION', 'Picks selection by tribe as a principle of leadership, instead of selection on merit.', '{"question":"Which is a principle of leadership and integrity?","wrong_answer":"Selection on tribe","correct_answer":"Selection on merit"}'::jsonb, 'The child has heard leaders chosen by community and thinks it is the rule.', 'Offer "Selection on tribe" next to the right answer in a new question and ask the child to choose.', 'Ask what a fair leader looks for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION.M_G8_CN_EXEC_LAWS', 'SOCI.G8.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION', 'Thinks the Executive makes laws because the President signs them.', '{"question":"The President signs a bill into law. Which arm made the law?","wrong_answer":"The Executive","correct_answer":"The Legislature (Parliament)"}'::jsonb, 'The signing is the visible moment.', 'Offer "The Executive" next to the right answer and ask the question again in a new context.', 'Trace a bill: debated and passed in Parliament, then signed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.HUMAN_RIGHTS.HUMAN_RIGHTS.M_G8_HR8_DUTY', 'SOCI.G8.POLITI.HUMAN_RIGHTS.HUMAN_RIGHTS', 'Says rights come without responsibilities.', '{"question":"What comes with a right?","wrong_answer":"Nothing, rights are free of duties","correct_answer":"A responsibility to respect the rights of others"}'::jsonb, 'Rights are taught as what you are owed, so duties seem separate.', 'Offer "Nothing, rights are free of duties" next to the right answer in a new question and ask the child to choose.', 'Ask what happens if everyone uses their right to noise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.HUMAN_RIGHTS.HUMAN_RIGHTS.M_G8_HR8_CHILD', 'SOCI.G8.POLITI.HUMAN_RIGHTS.HUMAN_RIGHTS', 'Says only adults have rights.', '{"question":"Do children have rights in Kenya?","wrong_answer":"No, only adults","correct_answer":"Yes, such as education, health care and protection"}'::jsonb, 'Children are told to obey adults, so they think rights belong to adults.', 'Offer "No, only adults" next to the right answer in a new question and ask the child to choose.', 'Ask the child to name a right they have.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.HUMAN_RIGHTS.HUMAN_RIGHTS.M_G8_HR8_REPORT', 'SOCI.G8.POLITI.HUMAN_RIGHTS.HUMAN_RIGHTS', 'Says a child who is abused should keep quiet.', '{"question":"A child is being abused. What should a person do?","wrong_answer":"Keep quiet to avoid trouble","correct_answer":"Tell a trusted adult or call Childline 116"}'::jsonb, 'Children are often told not to share family matters and fear getting into trouble.', 'Offer "Keep quiet to avoid trouble" next to the right answer in a new question and ask the child to choose.', 'Ask who they could tell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.HUMAN_RIGHTS.HUMAN_RIGHTS.M_G8_HR8_EDU_FEES', 'SOCI.G8.POLITI.HUMAN_RIGHTS.HUMAN_RIGHTS', 'Thinks basic education is a right only for children whose parents pay.', '{"question":"Is free and compulsory basic education a right of every child in Kenya?","wrong_answer":"Only for those who pay","correct_answer":"Yes, every child"}'::jsonb, 'The child hears about fees.', 'Offer "Only for those who pay" next to the right answer and ask the question again in a new context.', 'Read the right from the Bill of Rights.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.HUMAN_RIGHTS.HR_COMMUNICATE.M_G8_HC_RUMOUR', 'SOCI.G8.POLITI.HUMAN_RIGHTS.HR_COMMUNICATE', 'Thinks spreading the news as a rumour is a way to raise a rights issue.', '{"question":"You learn a neighbour''s child is kept from school to work. What is the right way to raise it?","wrong_answer":"Tell everyone in the village as gossip","correct_answer":"Tell a teacher, the chief or the children''s office with the facts"}'::jsonb, 'Talking about it feels like doing something.', 'Offer "Tell everyone in the village as gossip" next to the right answer and ask the question again in a new context.', 'Compare what gossip does with what a report to the chief does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.HUMAN_RIGHTS.HR_COMMUNICATE.M_G8_HC_SHOUT', 'SOCI.G8.POLITI.HUMAN_RIGHTS.HR_COMMUNICATE', 'Thinks shouting and threats make people listen on a rights issue.', '{"question":"Which is the most effective way to raise a rights issue with a leader?","wrong_answer":"Shout and threaten","correct_answer":"Speak clearly and calmly and give the facts"}'::jsonb, 'Loud protests on the news seem to get results.', 'Offer "Shout and threaten" next to the right answer and ask the question again in a new context.', 'Role-play both ways and ask which the leader would act on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.HUMAN_RIGHTS.HR_COMMUNICATE.M_G8_HC_NO_FOLLOWUP', 'SOCI.G8.POLITI.HUMAN_RIGHTS.HR_COMMUNICATE', 'Thinks the job is finished once the issue is reported.', '{"question":"You reported a rights issue a month ago and nothing happened. What next?","wrong_answer":"Forget it","correct_answer":"Follow up politely or go to another office"}'::jsonb, 'Reporting feels like the end.', 'Offer "Forget it" next to the right answer and ask the question again in a new context.', 'Add "follow up" as the last step on the board.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.HUMAN_RIGHTS.HR_COMMUNICATE.M_G8_HC_WRONG_CHANNEL', 'SOCI.G8.POLITI.HUMAN_RIGHTS.HR_COMMUNICATE', 'Takes a rights issue to someone who cannot act on it.', '{"question":"A child is being abused at home. Who should you tell?","wrong_answer":"A friend at school who keeps secrets","correct_answer":"A trusted adult such as a teacher, or Childline 116"}'::jsonb, 'Friends are the people the child talks to most.', 'Offer "A friend at school who keeps secrets" next to the right answer and ask the question again in a new context.', 'List people who can act: teacher, chief, police, children''s office, Childline.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.CITIZENSHIP.CITIZENSHIP.M_G8_CZ8_LOCAL', 'SOCI.G8.POLITI.CITIZENSHIP.CITIZENSHIP', 'Says a global citizen cares only about their own country.', '{"question":"Which is a quality of a global citizen?","wrong_answer":"Caring only about my own country","correct_answer":"Respecting other cultures and caring for the environment"}'::jsonb, 'Loyalty to one''s country is mixed up with caring only for it.', 'Offer "Caring only about my own country" next to the right answer in a new question and ask the child to choose.', 'Ask what a river polluted upstream does downstream.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.CITIZENSHIP.CITIZENSHIP.M_G8_CZ8_EAC', 'SOCI.G8.POLITI.CITIZENSHIP.CITIZENSHIP', 'Names Egypt as an East African Community member because it shares the Nile with East Africa.', '{"question":"Which country is a member of the East African Community?","wrong_answer":"Egypt","correct_answer":"Rwanda"}'::jsonb, 'The child links the Nile countries together.', 'Offer "Egypt" next to the right answer in a new question and ask the child to choose.', 'Look at a map of East Africa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.CITIZENSHIP.CITIZENSHIP.M_G8_CZ8_HARMONY', 'SOCI.G8.POLITI.CITIZENSHIP.CITIZENSHIP', 'Picks looking down on other groups as a factor of harmony.', '{"question":"Which helps citizens of East Africa live in harmony?","wrong_answer":"Looking down on other groups","correct_answer":"Respect and a shared language, Kiswahili"}'::jsonb, 'The child misreads the question or thinks pride in one''s own group brings order.', 'Offer "Looking down on other groups" next to the right answer in a new question and ask the child to choose.', 'Ask what unites a market in a border town.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G8.POLITI.CITIZENSHIP.CITIZENSHIP.M_G8_CZ8_NOBEL_SPORT', 'SOCI.G8.POLITI.CITIZENSHIP.CITIZENSHIP', 'Thinks the Nobel Peace Prize is a sports award.', '{"question":"Why did Wangari Maathai win the Nobel Peace Prize?","wrong_answer":"For winning a race","correct_answer":"For the Green Belt Movement, planting trees and standing up for justice"}'::jsonb, 'Kenya is famous for athletics prizes.', 'Offer "For winning a race" next to the right answer and ask the question again in a new context.', 'Show a photo of tree planting with the Green Belt Movement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
